import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { ApiService } from '../../../core/services/api.service';

@Component({
  selector: 'app-favorites',
  standalone: true,
  imports: [CommonModule, RouterModule],
  template: `
    <div class="page-header"><div class="container"><h1>Địa Điểm Yêu Thích</h1></div></div>
    <section class="section">
      <div class="container">
        <div class="loading-spinner" *ngIf="loading"><div class="spinner"></div></div>
        <div class="grid grid-3" *ngIf="!loading">
          <a *ngFor="let f of favorites" [routerLink]="['/destinations', f.destination.slug]" class="card dest-card fade-in">
            <div class="card-image">
              <img [src]="f.destination.images?.[0]?.url || 'https://picsum.photos/seed/' + f.destination.slug + '/400/300'" [alt]="f.destination.name">
            </div>
            <div class="card-body">
              <h3>{{ f.destination.name }}</h3>
              <p><span class="material-icons" style="font-size:1rem;vertical-align:middle;">location_on</span> {{ f.destination.province?.name }}</p>
              <div class="rating"><span class="score">{{ f.destination.rating }}</span><span class="stars">★★★★★</span></div>
            </div>
          </a>
        </div>
        <div class="empty-state" *ngIf="!loading && favorites.length === 0">
          <span class="material-icons">favorite_border</span>
          <h3>Chưa có địa điểm yêu thích</h3>
          <a routerLink="/destinations" class="btn btn-primary">Khám phá ngay</a>
        </div>
      </div>
    </section>
  `,
  styles: [`
    .dest-card { text-decoration: none; color: inherit; display: block; }
    .card-image { height: 180px; overflow: hidden; img { width: 100%; height: 100%; object-fit: cover; } }
    h3 { font-size: 1rem; margin-bottom: 0.5rem; }
    p { color: var(--gray); font-size: 0.875rem; margin-bottom: 0.5rem; }
    .rating { display: flex; align-items: center; gap: 0.25rem; .score { font-weight: 700; } .stars { color: #f59e0b; font-size: 0.875rem; } }
  `]
})
export class FavoritesComponent implements OnInit {
  favorites: any[] = [];
  loading = true;
  constructor(private api: ApiService) {}
  ngOnInit() { this.api.getFavorites().subscribe(data => { this.favorites = data; this.loading = false; }, () => { this.loading = false; }); }
}
